if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/course/lib.php');
require_once($CFG->dirroot . '/mod/customcert/lib.php');

$course = $DB->get_record('course', ['shortname' => 'CCERTDEMO01'], '*', MUST_EXIST);
$module = $DB->get_record('modules', ['name' => 'customcert'], '*', MUST_EXIST);
$admin = get_admin();
\core\session\manager::set_user($admin);
$now = time();
$cm = (object)[
    'course'       => $course->id,
    'module'       => $module->id,
    'instance'     => 0,
    'section'      => 1,
    'idnumber'     => '',
    'added'        => $now,
    'score'        => 0,
    'indent'       => 0,
    'visible'      => 1,
    'visibleold'   => 1,
    'groupmode'    => 0,
    'groupingid'   => 0,
    'completion'   => 0,
    'showdescription' => 0,
];
$cmid = add_course_module($cm);
course_add_cm_to_section($course->id, $cmid, 1);
$data = (object)[
    'course'        => $course->id,
    'coursemodule'  => $cmid,
    'name'          => 'Sample certificate',
    'intro'         => '<p>Open this activity to try <strong>mod_customcert</strong>: edit the certificate template (add text, images, or borders), then issue and download a PDF. Log in as <strong>student / test</strong> to issue a certificate showing your name, or as <strong>admin / test</strong> to edit the template.</p>',
    'introformat'   => FORMAT_HTML,
    'requiredtime'  => 0,
    'verifyany'     => 0,
    'deliveryoption'=> 'I',
    'protection_print'    => 0,
    'protection_modify'   => 0,
    'protection_copy'     => 0,
    'emailstudents' => 0,
    'emailteachers' => 0,
    'emailothers'   => '',
    'language'      => '',
];
$instanceid = customcert_add_instance($data, null);
$DB->set_field('course_modules', 'instance', $instanceid, ['id' => $cmid]);
rebuild_course_cache($course->id, true);
$cert = $DB->get_record('customcert', ['id' => $instanceid], '*', MUST_EXIST);
// The current public services do not provide a convenient element-creation API
// for non-form provisioning, so this demo inserts the seed elements directly.
$page = $DB->get_record('customcert_pages', ['templateid' => $cert->templateid], '*', MUST_EXIST);
$samples = [
    ['name' => 'Title',    'element' => 'text',        'fontsize' => 30, 'posy' => 50,  'colour' => '#1d3557',
     'data' => json_encode(['text' => 'Certificate of Completion', 'font' => 'freesans', 'fontsize' => 30, 'colour' => '#1d3557', 'width' => 170], JSON_THROW_ON_ERROR)],
    ['name' => 'Subtitle', 'element' => 'text',        'fontsize' => 14, 'posy' => 90,  'colour' => '#333333',
     'data' => json_encode(['text' => 'This certificate is proudly presented to', 'font' => 'freesans', 'fontsize' => 14, 'colour' => '#333333', 'width' => 170], JSON_THROW_ON_ERROR)],
    ['name' => 'Recipient', 'element' => 'studentname', 'fontsize' => 24, 'posy' => 115, 'colour' => '#000000',
     'data' => json_encode(['font' => 'freesans', 'fontsize' => 24, 'colour' => '#000000', 'width' => 170], JSON_THROW_ON_ERROR)],
    ['name' => 'Body',     'element' => 'text',        'fontsize' => 12, 'posy' => 145, 'colour' => '#333333',
     'data' => json_encode(['text' => 'for successfully completing the Moodle Playground demo course showcasing the mod_customcert activity.', 'font' => 'freesans', 'fontsize' => 12, 'colour' => '#333333', 'width' => 170], JSON_THROW_ON_ERROR)],
    ['name' => 'Footer',   'element' => 'text',        'fontsize' => 10, 'posy' => 245, 'colour' => '#666666',
     'data' => json_encode(['text' => 'Issued on the Moodle Playground preview', 'font' => 'freesans', 'fontsize' => 10, 'colour' => '#666666', 'width' => 170], JSON_THROW_ON_ERROR)],
];
$seq = 0;
foreach ($samples as $s) {
    $DB->insert_record('customcert_elements', (object)[
        'pageid'       => $page->id,
        'name'         => $s['name'],
        'element'      => $s['element'],
        'data'         => $s['data'],
        'posx'         => 20,
        'posy'         => $s['posy'],
        'refpoint'     => 0,
        'alignment'    => 'C',
        'sequence'     => $seq++,
        'timecreated'  => $now,
        'timemodified' => $now,
    ]);
}
echo "Seeded " . count($samples) . " elements on page {$page->id}\n";
echo "Created mod_customcert instance id={$instanceid} cmid={$cmid} in course {$course->shortname}\n";
